 	if (ret == NULL) {
 	    q->prev = NULL;
 	    ret = p = q;
@@ -4404,6 +4404,9 @@ xmlStaticCopyNodeList(xmlNodePtr node, xmlDocPtr doc, xmlNodePtr parent) {
 	node = node->next;
     }
     return(ret);
